.sl-method-video {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    font-family: var(--smartlearn-body-font, inherit);
    padding-block: clamp(3.5rem, 6vw, 6rem);
}
.sl-method-video h2,
.sl-method-video h3 {
    font-family: var(--smartlearn-heading-font, inherit);
}
.sl-method-video .sl-text-muted {
    color: var(--smartlearn-text-muted);
}
.sl-method-video .sl-container-boxed {
    max-width: 1240px;
    margin: 0 auto;
    padding-inline: 1.5rem;
}
@media (min-width: 992px) {
    .sl-method-video .sl-container-boxed {
        padding-inline: 2.5rem;
    }
}
.sl-method-video .sl-badge-eyebrow {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent);
    color: var(--smartlearn-primary);
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.12em;
}
.sl-method-video .sl-method-heading {
    font-size: clamp(2.2rem, 3.6vw, 3.1rem);
    font-weight: 800;
    line-height: 1.16;
    letter-spacing: -0.035em;
    color: var(--smartlearn-text);
}
.sl-method-video .sl-method-lead {
    font-size: 1.125rem;
    line-height: 1.75;
    color: var(--smartlearn-text-muted);
}
.sl-method-video .sl-accordion-btn {
    padding: 1.15rem 1.65rem;
    background-color: transparent;
    border: 1.5px solid color-mix(in srgb, var(--smartlearn-primary) 30%, var(--smartlearn-card-border));
    color: var(--smartlearn-text);
    transition: border-color 0.3s ease, background-color 0.3s ease, transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    cursor: pointer;
    box-shadow: 0 4px 15px color-mix(in srgb, var(--smartlearn-text) 4%, transparent);
}
.sl-method-video .sl-accordion-btn:hover {
    border-color: var(--smartlearn-primary);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 8%, transparent);
    transform: translateX(4px);
}
[dir="rtl"] .sl-method-video .sl-accordion-btn:hover {
    transform: translateX(-4px);
}
.sl-method-video .sl-accordion-btn:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
.sl-method-video .sl-accordion-title {
    font-size: 0.98rem;
    letter-spacing: 0.06em;
    font-weight: 700;
}
.sl-method-video .sl-accordion-icon {
    width: 42px;
    height: 42px;
    background-color: color-mix(in srgb, var(--smartlearn-text) 12%, transparent);
    color: var(--smartlearn-text);
    transition: background-color 0.3s ease, color 0.3s ease, transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}
.sl-method-video .sl-accordion-icon i {
    font-size: 14px;
}
[dir="rtl"] .sl-method-video .sl-accordion-icon i {
    transform: scaleX(-1);
}
.sl-method-video .sl-accordion-item.active .sl-accordion-btn {
    border-color: var(--smartlearn-primary);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 10%, transparent);
}
.sl-method-video .sl-accordion-item.active .sl-accordion-icon {
    background-color: var(--smartlearn-primary);
    color: var(--smartlearn-btn-text);
    transform: rotate(90deg);
}
[dir="rtl"] .sl-method-video .sl-accordion-item.active .sl-accordion-icon {
    transform: rotate(-90deg);
}
.sl-method-video .sl-accordion-body-wrapper {
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows 0.35s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.25s ease;
    opacity: 0;
}
.sl-method-video .sl-accordion-item.active .sl-accordion-body-wrapper {
    grid-template-rows: 1fr;
    opacity: 1;
}
.sl-method-video .sl-accordion-body {
    min-height: 0;
    overflow: hidden;
    padding-block: 1.25rem 0.5rem;
    padding-inline: 1.25rem 1.5rem;
    font-size: 1.05rem;
    line-height: 1.75;
}
.sl-method-video .sl-video-box {
    aspect-ratio: 16 / 9;
    background-color: var(--smartlearn-card-bg);
    border-color: var(--smartlearn-card-border);
}
.sl-method-video .sl-video-overlay {
    background: linear-gradient(180deg, rgba(0, 0, 0, 0.1) 0%, rgba(0, 0, 0, 0.5) 100%);
    transition: background 0.3s ease;
}
.sl-method-video .sl-play-btn {
    width: 68px;
    height: 68px;
    background-color: var(--smartlearn-primary);
    color: var(--smartlearn-btn-text);
    font-size: 1.5rem;
    transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s ease;
    cursor: pointer;
}
.sl-method-video .sl-play-btn:focus-visible {
    outline: 3px solid var(--smartlearn-btn-text);
    outline-offset: 3px;
}
.sl-method-video .sl-video-box:hover .sl-play-btn {
    transform: scale(1.12);
    box-shadow: 0 15px 30px rgba(0, 0, 0, 0.3);
}
.sl-method-video .sl-video-time-badge {
    background-color: rgba(0, 0, 0, 0.72);
    color: #fff;
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    z-index: 3;
}
.sl-method-video .sl-video-time-badge:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .sl-method-video .sl-accordion-btn,
    .sl-method-video .sl-accordion-icon,
    .sl-method-video .sl-accordion-body-wrapper,
    .sl-method-video .sl-play-btn {
        transition: none;
    }
    .sl-method-video .sl-accordion-btn:hover,
    .sl-method-video .sl-video-box:hover .sl-play-btn {
        transform: none;
    }
}

