(function() {
    function toSafeEmbedUrl(raw) {
        if (!raw) return null;
        try {
            const u = new URL(raw.trim(), window.location.href);
            if (u.protocol !== 'https:') return null;
            const host = u.hostname.replace(/^www\./, '').toLowerCase();
            if (host === 'youtube.com' || host === 'youtube-nocookie.com') {
                let id = u.searchParams.get('v');
                if (!id && u.pathname.startsWith('/embed/')) id = u.pathname.slice(7).split('/')[0];
                if (!id || !/^[A-Za-z0-9_-]{6,20}$/.test(id)) return null;
                return 'https://www.youtube-nocookie.com/embed/' + id + '?autoplay=1&rel=0';
            }
            if (host === 'youtu.be') {
                const id = u.pathname.slice(1).split('/')[0];
                if (!id || !/^[A-Za-z0-9_-]{6,20}$/.test(id)) return null;
                return 'https://www.youtube-nocookie.com/embed/' + id + '?autoplay=1&rel=0';
            }
            if (host === 'vimeo.com' || host === 'player.vimeo.com') {
                const parts = u.pathname.split('/').filter(Boolean);
                const id = parts[parts.length - 1];
                if (!id || !/^\d{4,15}$/.test(id)) return null;
                return 'https://player.vimeo.com/video/' + id + '?autoplay=1';
            }
        } catch (_) {
            return null;
        }
        return null;
    }

    function initMethodVideo(root) {
        if (root.dataset.slInit === '1') return;
        root.dataset.slInit = '1';

        const items = Array.from(root.querySelectorAll('.sl-accordion-item'));
        const headers = items.map(it => it.querySelector('.sl-accordion-header')).filter(Boolean);
        const uid = 'sl-mv-' + Math.random().toString(36).slice(2, 8);

        items.forEach((item, idx) => {
            const btn = item.querySelector('.sl-accordion-header');
            const panel = item.querySelector('.sl-accordion-body-wrapper');
            if (!btn || !panel) return;
            const btnId = uid + '-btn-' + idx;
            const panelId = uid + '-panel-' + idx;
            btn.id = btnId;
            btn.setAttribute('aria-controls', panelId);
            panel.id = panelId;
            panel.setAttribute('aria-labelledby', btnId);
            const active = item.classList.contains('active');
            btn.setAttribute('aria-expanded', active ? 'true' : 'false');
            if (active) panel.removeAttribute('hidden');
            else panel.setAttribute('hidden', '');
        });

        function setOpen(targetIndex) {
            items.forEach((item, idx) => {
                const btn = item.querySelector('.sl-accordion-header');
                const panel = item.querySelector('.sl-accordion-body-wrapper');
                const shouldOpen = idx === targetIndex && !item.classList.contains('active');
                item.classList.toggle('active', shouldOpen);
                if (btn) btn.setAttribute('aria-expanded', shouldOpen ? 'true' : 'false');
                if (panel) {
                    if (shouldOpen) panel.removeAttribute('hidden');
                    else panel.setAttribute('hidden', '');
                }
            });
        }

        headers.forEach((btn, idx) => {
            btn.addEventListener('click', (e) => {
                e.preventDefault();
                setOpen(idx);
            });
            btn.addEventListener('keydown', (e) => {
                let next = -1;
                if (e.key === 'ArrowDown') next = (idx + 1) % headers.length;
                else if (e.key === 'ArrowUp') next = (idx - 1 + headers.length) % headers.length;
                else if (e.key === 'Home') next = 0;
                else if (e.key === 'End') next = headers.length - 1;
                if (next !== -1) {
                    e.preventDefault();
                    headers[next].focus();
                }
            });
        });

        const videoBox = root.querySelector('.sl-video-box');
        const playBtn = root.querySelector('.sl-play-btn');
        const poster = root.querySelector('.sl-video-poster');
        const overlay = root.querySelector('.sl-video-overlay');
        const timeBadge = root.querySelector('.sl-video-time-badge');

        if (videoBox && playBtn) {
            playBtn.addEventListener('click', (e) => {
                e.preventDefault();
                e.stopPropagation();
                const rawUrl = timeBadge ? timeBadge.getAttribute('href') : '';
                const embedUrl = toSafeEmbedUrl(rawUrl);
                if (!embedUrl) return;

                if (poster) poster.style.display = 'none';
                if (overlay) overlay.style.display = 'none';
                if (timeBadge) timeBadge.style.display = 'none';
                playBtn.style.display = 'none';

                const iframe = document.createElement('iframe');
                iframe.src = embedUrl;
                iframe.title = 'Course methodology overview video';
                iframe.referrerPolicy = 'strict-origin-when-cross-origin';
                iframe.style.position = 'absolute';
                iframe.style.inset = '0';
                iframe.style.width = '100%';
                iframe.style.height = '100%';
                iframe.style.border = '0';
                iframe.style.zIndex = '10';
                iframe.setAttribute('allow', 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share');
                iframe.setAttribute('allowfullscreen', '');
                iframe.tabIndex = -1;
                videoBox.appendChild(iframe);
                iframe.focus();
            });
        }
    }

    function initAll() {
        document.querySelectorAll('.sl-method-video').forEach(initMethodVideo);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll);
    } else {
        initAll();
    }
})();
